'use strict';
const atlas=window.ATLAS;
const $=id=>document.getElementById(id);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('cs');
const upper=s=>s.charAt(0).toLocaleUpperCase('cs')+s.slice(1);
const safeImage=s=>typeof s==='string'&&/^images\/[a-zA-Z0-9_./-]+\.(?:jpe?g|png|webp|gif)$/i.test(s)&&!s.includes('..')?s:'';
const safeURL=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:''}catch{return ''}};
const months=['leden','únor','březen','duben','květen','červen','červenec','srpen','září','říjen','listopad','prosinec'];
const colors=[['bílá','#fffdf8','#3a382e'],['žlutá','#d9b654','#3a382e'],['oranžová','#ce8146','#fff'],['červená','#af5d50','#fff'],['růžová','#d49d9f','#3a382e'],['fialová','#8d7899','#fff'],['modrá','#7a98ac','#fff'],['zelená','#8c9973','#3a382e'],['hnědá','#94755c','#fff']];
let state={group:'',colors:new Set(),page:1};let opened=new Set();let galleryState=null;
const pageSize=40;
const plants=atlas.plants.map(p=>({...p,search:normalize([p.czech,p.latin,...p.aliases].join(' '))}));
const collator=new Intl.Collator('cs');
plants.sort((a,b)=>atlas.groups.indexOf(a.group)-atlas.groups.indexOf(b.group)||collator.compare(a.family_czech,b.family_czech)||collator.compare(a.genus,b.genus)||collator.compare(a.latin,b.latin));
$('total').textContent=plants.length;$('photo-count').textContent=atlas.images;
$('coverage').textContent=`Barva a doba kvetení jsou zatím doplněny u ${plants.filter(p=>p.months.length).length} položek. Tyto filtry hledají jen mezi vyplněnými údaji.`;
$('groups').innerHTML=[['','Všechny rostliny'],...atlas.groups.filter(g=>plants.some(p=>p.group===g)).map(g=>[g,g])].map(([value,label])=>`<button class="group-button${!value?' active':''}" type="button" data-group="${escapeHTML(value)}" aria-pressed="${!value}"><span>${escapeHTML(label)}</span><b>${plants.filter(p=>!value||p.group===value).length}</b></button>`).join('');
$('month').innerHTML+='<option value="unknown">Neuvedeno</option>'+months.map((m,i)=>`<option value="${i+1}">${upper(m)}</option>`).join('');
$('colors').innerHTML=colors.map(([name,hex,check])=>`<button type="button" class="color" style="background:${hex};--check:${check}" title="${name}" aria-label="${name}" aria-pressed="false" data-color="${name}"></button>`).join('');
function updateFamilies(){const previous=$('family').value;const names=[...new Set(plants.filter(p=>!state.group||p.group===state.group).map(p=>p.family))].sort((a,b)=>collator.compare(atlas.families.find(f=>f.latin===a).czech,atlas.families.find(f=>f.latin===b).czech));$('family').innerHTML='<option value="">Všechny čeledi</option>'+names.map(name=>{const f=atlas.families.find(f=>f.latin===name);return `<option value="${escapeHTML(name)}">${escapeHTML(f.czech)} (${escapeHTML(name)})</option>`}).join('');if(names.includes(previous))$('family').value=previous;}
function filtered(){const q=normalize($('search').value.trim());const tokens=q.split(/\s+/).filter(Boolean);const month=$('month').value;return plants.filter(p=>(!state.group||p.group===state.group)&&(!$('family').value||p.family===$('family').value)&&tokens.every(t=>p.search.includes(t))&&(!$('only-photos').checked||p.images.length)&&(!state.colors.size||p.colors.some(c=>state.colors.has(c)))&&(!month||(month==='unknown'?!p.months.length&&!p.nonflowering:p.months.includes(Number(month)))));}
function plantMarkup(p){const thumb=p.images[0];return `<details class="plant" id="${p.id}" data-id="${p.id}" ${opened.has(p.id)?'open':''}><summary>${thumb?`<img class="thumb" src="${safeImage(thumb.thumb||thumb.path)}" alt="" loading="lazy" width="44" height="44">`:'<span class="thumb thumb-empty" aria-hidden="true">·</span>'}<span class="plant-name"><strong>${escapeHTML(upper(p.czech))}</strong><em>(${escapeHTML(p.latin)})</em></span><span class="photo-number">${p.images.length?p.images.length+' foto':'bez fotografie'}</span></summary><div class="plant-content"></div></details>`;}
function fillDetail(el){if(el.dataset.loaded)return;el.dataset.loaded='1';const p=plants.find(p=>p.id===el.dataset.id);el.querySelector('.plant-content').innerHTML=`${p.aliases.length?`<p class="aliases">Další názvy: ${escapeHTML(p.aliases.join(', '))}</p>`:''}<dl class="traits"><div><dt>Čeleď</dt><dd>${escapeHTML(p.family_czech)} (<em>${escapeHTML(p.family)}</em>)</dd></div><div><dt>Úroveň záznamu</dt><dd>${escapeHTML(upper(p.rank))}</dd></div><div><dt>Barva květu</dt><dd>${p.nonflowering?'Výtrusná rostlina':escapeHTML(p.color_detail||'Neuvedeno')}</dd></div><div><dt>Doba kvetení</dt><dd>${p.nonflowering?'Netvoří květy':escapeHTML(p.flowering_detail||'Neuvedeno')}</dd></div></dl>${p.notes?`<p class="detail-label">Poznámky</p><p class="notes">${escapeHTML(p.notes)}</p>`:'<p class="aliases">Bez dalších poznámek.</p>'}${p.images.length?`<div class="gallery">${p.images.map((im,i)=>`<button type="button" data-plant="${p.id}" data-image="${i}" aria-label="Zvětšit: ${escapeHTML(p.czech)}, fotografie ${i+1}"><img src="${safeImage(im.path)}" alt="${escapeHTML(p.czech)} – fotografie ${i+1}" loading="lazy"></button>`).join('')}</div>`:'<p class="aliases">Fotografie zatím není přidaná.</p>'}${p.sources.length?`<a class="source-link" href="${escapeHTML(safeURL(p.sources[0]))}" target="_blank" rel="noopener">Zdroj doplněných údajů · Pladias ↗</a>`:''}`;}
function render(){let found=filtered();const sort=$('sort').value;if(sort==='czech')found.sort((a,b)=>collator.compare(a.czech,b.czech));else if(sort==='latin')found.sort((a,b)=>collator.compare(a.latin,b.latin));const pages=Math.max(1,Math.ceil(found.length/pageSize));state.page=Math.min(state.page,pages);const slice=found.slice((state.page-1)*pageSize,state.page*pageSize);$('result-count').textContent=`Zobrazeno ${found.length} z ${plants.length} položek`;$('title').textContent=state.group||'Všechny rostliny';$('reset').hidden=!state.group&&!state.colors.size&&!$('search').value&&!$('family').value&&!$('month').value&&!$('only-photos').checked&&sort==='taxonomy';let family='';$('results').innerHTML=slice.map(p=>{let heading='';if(sort==='taxonomy'&&family!==p.family){family=p.family;heading=`<div class="family-heading"><span class="group-label">${escapeHTML(p.group)}</span><h2>${escapeHTML(p.family_czech)}</h2><em>(${escapeHTML(p.family)})</em><small>${found.filter(x=>x.family===p.family).length} položek</small></div>`}return heading+plantMarkup(p)}).join('')||'<div class="empty"><h2>Žádná rostlina neodpovídá</h2><p>Zkus jiný název nebo zruš některý filtr.</p></div>';$('pagination').innerHTML=found.length>pageSize?`<button type="button" data-page="${state.page-1}" ${state.page===1?'disabled':''}>← Předchozí</button><span>${state.page} / ${pages}</span><button type="button" data-page="${state.page+1}" ${state.page===pages?'disabled':''}>Další →</button>`:'';document.querySelectorAll('.plant').forEach(el=>{if(el.open)fillDetail(el);el.addEventListener('toggle',()=>{if(el.open){opened.add(el.dataset.id);fillDetail(el)}else opened.delete(el.dataset.id)})});}
$('filters').addEventListener('submit',e=>e.preventDefault());$('search').addEventListener('input',()=>{state.page=1;render()});['family','month','sort','only-photos'].forEach(id=>$(id).addEventListener('change',()=>{state.page=1;render()}));
$('groups').addEventListener('click',e=>{const btn=e.target.closest('[data-group]');if(!btn)return;state.group=btn.dataset.group;state.page=1;$('family').value='';updateFamilies();document.querySelectorAll('[data-group]').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-pressed',String(b===btn))});render()});
$('colors').addEventListener('click',e=>{const b=e.target.closest('[data-color]');if(!b)return;const c=b.dataset.color;state.colors.has(c)?state.colors.delete(c):state.colors.add(c);b.setAttribute('aria-pressed',String(state.colors.has(c)));state.page=1;render()});
$('reset').addEventListener('click',()=>{$('filters').reset();state={group:'',colors:new Set(),page:1};document.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed','false'));document.querySelectorAll('[data-group]').forEach(b=>{b.classList.toggle('active',!b.dataset.group);b.setAttribute('aria-pressed',String(!b.dataset.group))});updateFamilies();render()});
$('pagination').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(!b||b.disabled)return;state.page=Number(b.dataset.page);render();$('result-count').scrollIntoView({block:'start'})});
function showPhoto(){const p=galleryState.plant,i=galleryState.index;const im=p.images[i];$('large-photo').src=safeImage(im.path);$('large-photo').alt=`${p.czech} (${p.latin}), fotografie ${i+1}`;$('lightbox-title').innerHTML=`${escapeHTML(upper(p.czech))} (<em>${escapeHTML(p.latin)}</em>)`;$('photo-caption').textContent=`${i+1} / ${p.images.length}`;$('prev-photo').disabled=p.images.length<2;$('next-photo').disabled=p.images.length<2;}
function movePhoto(delta){if(!galleryState)return;galleryState.index=(galleryState.index+delta+galleryState.plant.images.length)%galleryState.plant.images.length;showPhoto()}
$('results').addEventListener('click',e=>{const b=e.target.closest('[data-image]');if(!b)return;galleryState={plant:plants.find(p=>p.id===b.dataset.plant),index:Number(b.dataset.image)};showPhoto();$('lightbox').showModal()});$('prev-photo').addEventListener('click',()=>movePhoto(-1));$('next-photo').addEventListener('click',()=>movePhoto(1));$('lightbox').addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();movePhoto(1)}if(e.key==='ArrowLeft'){e.preventDefault();movePhoto(-1)}});document.querySelectorAll('dialog .close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$('about').addEventListener('click',()=>$('about-dialog').showModal());
updateFamilies();opened.add(plants[0].id);render();
